import SwiftUI

struct ExportTransactionsView: View {
    @State private var selectedRange = "All time"
    @State private var selectedAccount = "All accounts"
    @State private var selectedCategory = "All categories"

    // Replace with the URL generated by your CSV exporter.
    @State private var exportURL: URL?

    var body: some View {
        ScrollView {
            VStack(alignment: .leading, spacing: 24) {
                header

                VStack(spacing: 0) {
                    Menu {
                        Button("All time") { selectedRange = "All time" }
                        Button("This month") { selectedRange = "This month" }
                        Button("This year") { selectedRange = "This year" }
                    } label: {
                        selectionRow("Date range", value: selectedRange)
                    }

                    Divider()

                    Menu {
                        Button("All accounts") { selectedAccount = "All accounts" }
                        // Add accounts from your database.
                    } label: {
                        selectionRow("Accounts", value: selectedAccount)
                    }

                    Divider()

                    Menu {
                        Button("All categories") { selectedCategory = "All categories" }
                        // Add categories from your database.
                    } label: {
                        selectionRow("Categories", value: selectedCategory)
                    }
                }
                .background(ArgiColors.cardBackground)
                .clipShape(RoundedRectangle(cornerRadius: 20))

                exportSummary

                if let exportURL {
                    ShareLink(item: exportURL) {
                        Label("Export & Share", systemImage: "square.and.arrow.up")
                            .font(.headline)
                            .frame(maxWidth: .infinity)
                            .padding()
                    }
                    .buttonStyle(.plain)
                    .foregroundStyle(.white)
                    .background(ArgiColors.blue)
                    .clipShape(RoundedRectangle(cornerRadius: 16))
                } else {
                    Button {
                        // Generate the CSV and assign its URL to exportURL.
                    } label: {
                        Label("Prepare Export", systemImage: "square.and.arrow.up")
                            .font(.headline)
                            .frame(maxWidth: .infinity)
                            .padding()
                    }
                    .buttonStyle(.plain)
                    .foregroundStyle(.white)
                    .background(ArgiColors.blue)
                    .clipShape(RoundedRectangle(cornerRadius: 16))
                }

                DataInfoBox(
                    icon: "info.circle",
                    title: "Save or share",
                    message: "Choose where to save or share your file, including Files, Mail, AirDrop and more."
                )

                Divider()

                HStack(spacing: 14) {
                    Image(systemName: "chart.bar.fill")
                        .font(.title2)
                        .foregroundStyle(ArgiColors.green)
                        .frame(width: 48, height: 48)
                        .background(ArgiColors.green.opacity(0.10))
                        .clipShape(RoundedRectangle(cornerRadius: 12))

                    VStack(alignment: .leading, spacing: 4) {
                        Text("Open in Numbers")
                            .font(.subheadline.weight(.semibold))

                        Text("The exported CSV file can be opened in Numbers, Excel and Google Sheets.")
                            .font(.caption)
                            .foregroundStyle(ArgiColors.secondaryText)
                    }
                }
            }
            .padding(20)
        }
        .background(ArgiColors.background)
        .navigationTitle("Export")
        .navigationBarTitleDisplayMode(.inline)
    }

    private var header: some View {
        HStack(alignment: .center, spacing: 18) {
            Image(systemName: "square.and.arrow.up")
                .font(.system(size: 34))
                .foregroundStyle(ArgiColors.blue)
                .frame(width: 88, height: 88)
                .background(ArgiColors.blue.opacity(0.10))
                .clipShape(RoundedRectangle(cornerRadius: 22))

            VStack(alignment: .leading, spacing: 8) {
                Text("Export Transactions")
                    .font(.title3.bold())

                Text("Create a CSV file with your transactions to save or share.")
                    .font(.subheadline)
                    .foregroundStyle(ArgiColors.secondaryText)
            }
        }
    }

    private func selectionRow(_ title: String, value: String) -> some View {
        HStack {
            Text(title)
                .foregroundStyle(ArgiColors.primaryText)

            Spacer()

            Text(value)
                .foregroundStyle(ArgiColors.secondaryText)

            Image(systemName: "chevron.right")
                .font(.caption.weight(.semibold))
                .foregroundStyle(.tertiary)
        }
        .padding(18)
        .contentShape(Rectangle())
    }

    private var exportSummary: some View {
        VStack(spacing: 16) {
            summaryRow("Transactions", value: "248", icon: "doc")
            summaryRow("Date range", value: selectedRange, icon: "calendar")
            summaryRow("File name", value: "argi-transactions.csv", icon: "tag")
        }
        .padding(20)
        .background(ArgiColors.blue.opacity(0.05))
        .clipShape(RoundedRectangle(cornerRadius: 20))
    }

    private func summaryRow(
        _ title: String,
        value: String,
        icon: String
    ) -> some View {
        HStack(spacing: 14) {
            Image(systemName: icon)
                .frame(width: 22)
                .foregroundStyle(ArgiColors.secondaryText)

            Text(title)
                .foregroundStyle(ArgiColors.secondaryText)

            Spacer()

            Text(value)
                .fontWeight(.medium)
                .lineLimit(1)
                .minimumScaleFactor(0.8)
        }
        .font(.subheadline)
    }
}
